#include <rs485_hal.h>
#include "main.h"    // STM32CubeMX generated
#include "stm32f3xx_hal.h"   // STM32CubeMX generated
#include "stm32f3xx_hal_uart.h"
#include <stddef.h>     // For size_t
#include <stdint.h>

// Instantiate the global variable the flight code expects
mss_uart_instance_t g_mss_uart0;
// Forward declare the STM32 HAL UART handle (generated by CubeMX)
extern UART_HandleTypeDef huart2;

void rs485_tx_enable(void) {
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET);   // DE = HIGH
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_6, GPIO_PIN_SET);   // ~RE = HIGH (disable RX)
}

void rs485_rx_enable(void) {
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET); // DE = LOW
    HAL_GPIO_WritePin(GPIOA, GPIO_PIN_6, GPIO_PIN_RESET); // ~RE = LOW (enable RX)
}

void prvUARTSend(mss_uart_instance_t *pxUART, const uint8_t *pcBuffer, size_t xBufferLength)
{
    // We ignore pxUART and just use the STM32 HAL handle for USART2
    HAL_UART_Transmit(&huart2, (uint8_t *)pcBuffer, xBufferLength, HAL_MAX_DELAY);

    // Wait for the physical transmission to complete (TXE/TC flags)
    // This ensures the shift register is empty before the 1ms delay in st16_test.c finishes
    while (HAL_UART_GetState(&huart2) & HAL_UART_STATE_BUSY_TX) {
        // Optional: Add a timeout counter here for production safety
    }
}

void hal_uart_send(const uint8_t *data, uint16_t len) {
    rs485_tx_enable();

    // Blocking transmit (simple, good for testing)
    HAL_UART_Transmit(&huart2, (uint8_t *)data, len, HAL_MAX_DELAY);

    // CRITICAL: Wait for the shift register to empty before
    // switching back to RX, or the last byte gets corrupted.
    while (HAL_UART_GetState(&huart2) & HAL_UART_STATE_BUSY_TX);

    rs485_rx_enable();
}

int hal_uart_receive(uint8_t *data, uint16_t max_len, uint32_t timeout_ms) {
    // For a quick test, use a simple polling approach:
    uint16_t count = 0;
    while (count < max_len) {
        if (HAL_UART_Receive(&huart2, &data[count], 1, timeout_ms) == HAL_OK) {
            count++;
        } else {
            break; // Timeout — no more data
        }
    }
    return count;
}
